package gg.jte.convert.jsp;

import gg.jte.convert.ConverterOutput;
import gg.jte.convert.CustomTagConverter;
import gg.jte.convert.IoUtils;
import gg.jte.convert.cc.CamelCaseConverter;
import gg.jte.convert.jsp.converter.*;
import org.apache.jasper.JasperException;
import org.apache.jasper.compiler.JtpConverter;
import org.apache.jasper.compiler.JtpCustomTag;
import org.xml.sax.Attributes;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.MalformedURLException;
import java.net.URISyntaxException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;

public class JspToJteConverter {

    private static final Pattern UNCONVERTED_TAG_REFERENCES = Pattern.compile("<[a-zA-Z0-9\\-]+:[a-zA-Z0-9\\-]+\\b");
    private static final Pattern JSP_COMMENT = Pattern.compile("<%--.*?--%>", Pattern.DOTALL);

    public static void convertFromIntelliJPlugin(String[] commandLineArgs, JspToJteConverter converter, Consumer<Converter> parserSetup) {
        if (commandLineArgs.length < 1) {
            throw new IllegalArgumentException("Missing JSP file, it should be the first argument on the command line.");
        }

        Path jspFile = Paths.get(commandLineArgs[0]);
        jspFile = converter.jspRoot.toAbsolutePath().relativize(jspFile);

        converter.convertTag(jspFile.toString(), parserSetup);
    }

    private final Path jspRoot;
    private final Path jteRoot;
    private final String jteTag;

    public JspToJteConverter(Path jspRoot, Path jteRoot, String jteTag) {
        this.jspRoot = jspRoot;
        this.jteRoot = jteRoot;
        this.jteTag = jteTag;
    }

    public void convertTag(String jspTag, Consumer<Converter> parserSetup) {
        Path jspTagFile = jspRoot.resolve(jspTag);
        String relativeFilePath = jspRoot.relativize(jspTagFile).toString();
        JtpConverter converter = createConverter(relativeFilePath, readFile(jspTagFile), parserSetup);
        String jte = converter.convert();

        System.out.println(jte);

        checkDependencies(jte);

        String jteTemplate = suggestJteFile(jspTag.replace('\\', '/'));
        Path jteTemplateFile = jteRoot.resolve(jteTemplate);
        IoUtils.writeFile(jteTemplateFile, jte);

        replaceUsages(jspTagFile, jteTemplateFile);
    }

    public JspMigrationPlan planTags(Collection<String> jspTags, Consumer<Converter> parserSetup) {
        if (jspTags == null || jspTags.isEmpty()) {
            throw new IllegalArgumentException("At least one JSP tag must be selected.");
        }

        Path absoluteJspRoot = jspRoot.toAbsolutePath().normalize();
        Path absoluteJteRoot = jteRoot.toAbsolutePath().normalize();
        Map<String, SelectedTag> selectedByRelativePath = new TreeMap<>();
        Map<String, SelectedTag> selectedByInvocation = new HashMap<>();
        for (String jspTag : jspTags) {
            SelectedTag selected = validateSelectedTag(jspTag, absoluteJspRoot);
            if (selectedByRelativePath.putIfAbsent(selected.relativePath, selected) != null) {
                throw new IllegalArgumentException("Duplicate selected JSP tag: " + selected.relativePath);
            }
            SelectedTag ambiguous = selectedByInvocation.putIfAbsent(selected.invocationName, selected);
            if (ambiguous != null) {
                throw new IllegalArgumentException("Ambiguous selected JSP invocation <" + selected.invocationName + ">: "
                        + ambiguous.relativePath + " and " + selected.relativePath);
            }
        }

        Map<Path, JspMigrationPlan.Snapshot> snapshots = new TreeMap<>(Comparator.comparing(Path::toString));
        Map<Path, String> virtualFiles = scanUsageFiles(absoluteJspRoot, snapshots);
        Map<Path, String> destinationOwners = new HashMap<>();
        Set<Path> generatedDestinations = new LinkedHashSet<>();
        for (SelectedTag selected : selectedByRelativePath.values()) {
            String suggested = suggestJteFile(selected.relativePath);
            if (suggested == null || suggested.isBlank()) {
                throw new IllegalArgumentException("Generated JTE destination is blank for " + selected.relativePath);
            }
            Path suggestedPath = Paths.get(suggested.replace('\\', '/'));
            Path destination = absoluteJteRoot.resolve(suggestedPath).normalize();
            if (suggestedPath.isAbsolute() || !destination.startsWith(absoluteJteRoot)) {
                throw new IllegalArgumentException("Generated JTE destination is outside the JTE root: " + destination);
            }
            rejectSymbolicDestinationAncestor(absoluteJteRoot, destination);
            if (Files.exists(destination, LinkOption.NOFOLLOW_LINKS)) {
                throw new IllegalArgumentException("Generated JTE destination is already taken: " + destination);
            }
            String owner = destinationOwners.putIfAbsent(destination, selected.relativePath);
            if (owner != null) {
                throw new IllegalArgumentException("Generated JTE destinations collide for " + owner + " and " + selected.relativePath + ": " + destination);
            }
            selected.destination = destination;
            generatedDestinations.add(destination);
        }

        Map<SelectedTag, JtpConverter> converters = new HashMap<>();
        Map<SelectedTag, Set<SelectedTag>> dependencies = new HashMap<>();
        for (SelectedTag selected : selectedByRelativePath.values()) {
            String content = readFile(selected.source);
            JtpConverter converter = createConverter(selected.relativePath, content, parserSetup);
            converters.put(selected, converter);

            for (String approvedInclude : converter.getInlinedIncludes()) {
                snapshotInclude(approvedInclude, absoluteJspRoot, snapshots);
            }

            Set<SelectedTag> selectedDependencies = new TreeSet<>(Comparator.comparing(tag -> tag.relativePath));
            for (String customTag : converter.discoverCustomTags()) {
                SelectedTag dependency = selectedByInvocation.get(customTag);
                if (dependency != null) {
                    selectedDependencies.add(dependency);
                }
            }
            for (String included : converter.getDiscoveredIncludes()) {
                snapshotInclude(included, absoluteJspRoot, snapshots);
            }
            dependencies.put(selected, selectedDependencies);
        }

        List<SelectedTag> orderedTags = order(selectedByRelativePath.values(), dependencies);
        Map<Path, String> generatedWrites = new LinkedHashMap<>();
        Set<SelectedTag> converted = new LinkedHashSet<>();
        for (SelectedTag selected : orderedTags) {
            JtpConverter converter = converters.get(selected);
            for (SelectedTag dependency : converted) {
                converter.register(dependency.invocationName,
                        new PlannedTagConverter(absoluteJteRoot.relativize(dependency.destination).toString().replace('\\', '/')));
            }
            String jte = converter.convert();
            checkDependencies(JSP_COMMENT.matcher(jte).replaceAll(""));
            generatedWrites.put(selected.destination, jte);
            converted.add(selected);

            virtualFiles.remove(selected.source);
            String oldPrefix = extractTagPrefix(selected.source);
            String oldClosing = "</" + oldPrefix.substring(1) + ">";
            String newJteFile = absoluteJteRoot.relativize(selected.destination).toString().replace('\\', '/');
            for (Map.Entry<Path, String> file : virtualFiles.entrySet()) {
                file.setValue(replaceUsages(file.getValue(), oldPrefix, oldClosing, newJteFile));
            }
        }

        Map<Path, String> writes = new LinkedHashMap<>(generatedWrites);
        for (Map.Entry<Path, String> file : virtualFiles.entrySet()) {
            JspMigrationPlan.Snapshot snapshot = snapshots.get(file.getKey());
            String original = new String(snapshotBytes(snapshot), StandardCharsets.UTF_8);
            if (!file.getValue().equals(original)) {
                writes.put(file.getKey(), file.getValue());
            }
        }

        List<Path> conversionOrder = new ArrayList<>();
        Set<Path> deletes = new LinkedHashSet<>();
        for (SelectedTag selected : orderedTags) {
            conversionOrder.add(selected.source);
            deletes.add(selected.source);
            writes.remove(selected.source);
        }
        return new JspMigrationPlan(conversionOrder, deletes, writes, snapshots, generatedDestinations);
    }

    private static byte[] snapshotBytes(JspMigrationPlan.Snapshot snapshot) {
        return snapshot.content();
    }

    private JtpConverter createConverter(String relativeFilePath, String content, Consumer<Converter> parserSetup) {
        JtpConverter converter = new JtpConverter(
                relativeFilePath,
                content.replace("\r", "").getBytes(StandardCharsets.UTF_8),
                getResourceBase(),
                relativeFilePath.endsWith(".tag"),
                new ConverterOutput()
        );

        converter.register("c:if", new JspIfConverter());
        converter.register("c:forEach", new JspForEachConverter());
        converter.register("c:choose", new JspChooseConverter());
        converter.register("c:when", new JspWhenConverter());
        converter.register("c:otherwise", new JspOtherwiseConverter());
        converter.register("c:set", new JspSetConverter());
        converter.register("fmt:message", new JstlFmtMessageConverter());
        converter.register("fmt:param", new JstlFmtParamConverter());
        converter.register(this.jteTag, new JspJteConverter());

        String[] notConvertedTags = getNotConvertedTags();
        if (notConvertedTags != null) {
            for (String notConvertedTag : notConvertedTags) {
                converter.register(notConvertedTag, new JspNoopConverter());
            }
        }
        if (parserSetup != null) {
            parserSetup.accept(converter);
        }
        return converter;
    }

    private SelectedTag validateSelectedTag(String jspTag, Path absoluteJspRoot) {
        if (jspTag == null || jspTag.isBlank()) {
            throw new IllegalArgumentException("Selected JSP tag paths must not be null or blank.");
        }
        String portablePath = jspTag.replace('\\', '/');
        if (portablePath.startsWith("/") || portablePath.matches("^[a-zA-Z]:/.*")) {
            throw new IllegalArgumentException("Selected JSP tag paths must be root-relative: " + jspTag);
        }
        Path relative = Paths.get(portablePath).normalize();
        Path source = absoluteJspRoot.resolve(relative).normalize();
        if (relative.toString().isEmpty() || !source.startsWith(absoluteJspRoot)) {
            throw new IllegalArgumentException("Selected JSP tag is outside the JSP root: " + jspTag);
        }
        String normalizedRelative = absoluteJspRoot.relativize(source).toString().replace('\\', '/');
        if (!normalizedRelative.endsWith(".tag")) {
            throw new IllegalArgumentException("Selected JSP input is not a .tag file: " + jspTag);
        }
        if (Files.isSymbolicLink(source)) {
            throw new IllegalArgumentException("Selected JSP tag must not be a symbolic link: " + source);
        }
        if (!Files.isRegularFile(source, LinkOption.NOFOLLOW_LINKS)) {
            throw new IllegalArgumentException("Selected JSP tag is missing or not a regular file: " + source);
        }
        return new SelectedTag(normalizedRelative, source, invocationName(source));
    }

    private Map<Path, String> scanUsageFiles(Path absoluteJspRoot, Map<Path, JspMigrationPlan.Snapshot> snapshots) {
        Map<Path, String> files = new TreeMap<>(Comparator.comparing(Path::toString));
        try (Stream<Path> stream = Files.walk(absoluteJspRoot)) {
            stream.filter(Files::isRegularFile)
                    .map(path -> path.toAbsolutePath().normalize())
                    .filter(this::isUsageFile)
                    .sorted(Comparator.comparing(Path::toString))
                    .forEach(path -> {
                        byte[] bytes = readBytes(path);
                        snapshots.put(path, new JspMigrationPlan.Snapshot(path, bytes));
                        files.put(path, new String(bytes, StandardCharsets.UTF_8));
                    });
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return files;
    }

    private boolean isUsageFile(Path path) {
        String file = path.toString();
        return file.endsWith(".jsp") || file.endsWith(".jsp.inc") || file.endsWith(".tag");
    }

    private void snapshotInclude(String include, Path absoluteJspRoot, Map<Path, JspMigrationPlan.Snapshot> snapshots) {
        Path included = resolveInclude(include);
        if (!included.startsWith(absoluteJspRoot)) {
            throw new IllegalArgumentException("Approved include is outside the JSP root: " + included);
        }
        if (!Files.isRegularFile(included)) {
            throw new IllegalArgumentException("Approved include is missing or not a regular file: " + included);
        }
        snapshots.computeIfAbsent(included, path -> new JspMigrationPlan.Snapshot(path, readBytes(path)));
