    private Path resolveInclude(String include) {
        try {
            URL resourceBase = getResourceBase();
            if (!"file".equalsIgnoreCase(resourceBase.getProtocol())) {
                throw new IllegalArgumentException("Approved includes require a file resource base: " + resourceBase);
            }
            Path base = Paths.get(resourceBase.toURI()).toAbsolutePath().normalize();
            String relativeInclude = include.replace('\\', '/');
            while (relativeInclude.startsWith("/")) {
                relativeInclude = relativeInclude.substring(1);
            }
            return base.resolve(relativeInclude).normalize();
        } catch (URISyntaxException e) {
            throw new IllegalArgumentException("Invalid resource base for approved include.", e);
        }
    }

    private static byte[] readBytes(Path path) {
        try {
            return Files.readAllBytes(path);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static void rejectSymbolicDestinationAncestor(Path root, Path destination) {
        for (Path current = destination.getParent(); current != null && current.startsWith(root); current = current.getParent()) {
            if (Files.isSymbolicLink(current)) {
                throw new IllegalArgumentException("Generated JTE destination resolves through a symbolic link: " + destination);
            }
            if (current.equals(root)) {
                break;
            }
        }
    }

    private static List<SelectedTag> order(Collection<SelectedTag> selected,
                                           Map<SelectedTag, Set<SelectedTag>> dependencies) {
        List<SelectedTag> result = new ArrayList<>();
        Set<SelectedTag> remaining = new TreeSet<>(Comparator.comparing(tag -> tag.relativePath));
        remaining.addAll(selected);
        Set<SelectedTag> converted = new HashSet<>();
        while (!remaining.isEmpty()) {
            SelectedTag next = null;
            for (SelectedTag candidate : remaining) {
                if (converted.containsAll(dependencies.get(candidate))) {
                    next = candidate;
                    break;
                }
            }
            if (next == null) {
                List<SelectedTag> cycle = findCycle(remaining, dependencies);
                List<String> paths = new ArrayList<>();
                for (SelectedTag tag : cycle) {
                    paths.add(tag.relativePath);
                }
                throw new IllegalArgumentException("Cyclic JSP tag dependency: " + String.join(" -> ", paths));
            }
            remaining.remove(next);
            converted.add(next);
            result.add(next);
        }
        return result;
    }

    private static List<SelectedTag> findCycle(Set<SelectedTag> remaining,
                                               Map<SelectedTag, Set<SelectedTag>> dependencies) {
        Map<SelectedTag, Integer> state = new HashMap<>();
        List<SelectedTag> stack = new ArrayList<>();
        for (SelectedTag tag : remaining) {
            List<SelectedTag> cycle = findCycle(tag, remaining, dependencies, state, stack);
            if (cycle != null) {
                return cycle;
            }
        }
        throw new IllegalStateException("Failed to locate JSP tag dependency cycle.");
    }

    private static List<SelectedTag> findCycle(SelectedTag tag, Set<SelectedTag> remaining,
                                               Map<SelectedTag, Set<SelectedTag>> dependencies,
                                               Map<SelectedTag, Integer> state, List<SelectedTag> stack) {
        Integer currentState = state.get(tag);
        if (currentState != null) {
            if (currentState == 1) {
                int start = stack.indexOf(tag);
                List<SelectedTag> cycle = new ArrayList<>(stack.subList(start, stack.size()));
                cycle.add(tag);
                return cycle;
            }
            return null;
        }
        state.put(tag, 1);
        stack.add(tag);
        for (SelectedTag dependency : dependencies.get(tag)) {
            if (!remaining.contains(dependency)) {
                continue;
            }
            List<SelectedTag> cycle = findCycle(dependency, remaining, dependencies, state, stack);
            if (cycle != null) {
                return cycle;
            }
        }
        stack.remove(stack.size() - 1);
        state.put(tag, 2);
        return null;
    }

