    private boolean isUsageFile(Path path) {
        String file = path.toString();
        return file.endsWith(".jsp") || file.endsWith(".jsp.inc") || file.endsWith(".tag");
    }

    private void snapshotInclude(String include, Path absoluteJspRoot, Map<Path, JspMigrationPlan.Snapshot> snapshots) {
        Path included = resolveInclude(include);
        if (!included.startsWith(absoluteJspRoot)) {
            throw new IllegalArgumentException("Approved include is outside the JSP root: " + included);
        }
        if (!Files.isRegularFile(included)) {
            throw new IllegalArgumentException("Approved include is missing or not a regular file: " + included);
        }
        snapshots.computeIfAbsent(included, path -> new JspMigrationPlan.Snapshot(path, readBytes(path)));
    }

    private Path resolveInclude(String include) {
        try {
            URL resourceBase = getResourceBase();
            if (!"file".equalsIgnoreCase(resourceBase.getProtocol())) {
                throw new IllegalArgumentException("Approved includes require a file resource base: " + resourceBase);
            }
            Path base = Paths.get(resourceBase.toURI()).toAbsolutePath().normalize();
            String relativeInclude = include.replace('\\', '/');
            while (relativeInclude.startsWith("/")) {
                relativeInclude = relativeInclude.substring(1);
            }
            return base.resolve(relativeInclude).normalize();
        } catch (URISyntaxException e) {
            throw new IllegalArgumentException("Invalid resource base for approved include.", e);
        }
    }

    private static byte[] readBytes(Path path) {
        try {
            return Files.readAllBytes(path);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static void rejectSymbolicDestinationAncestor(Path root, Path destination) {
        for (Path current = destination.getParent(); current != null && current.startsWith(root); current = current.getParent()) {
            if (Files.isSymbolicLink(current)) {
                throw new IllegalArgumentException("Generated JTE destination resolves through a symbolic link: " + destination);
            }
            if (current.equals(root)) {
                break;
            }
        }
    }

    private static List<SelectedTag> order(Collection<SelectedTag> selected,
                                           Map<SelectedTag, Set<SelectedTag>> dependencies) {
        List<SelectedTag> result = new ArrayList<>();
        Set<SelectedTag> remaining = new TreeSet<>(Comparator.comparing(tag -> tag.relativePath));
        remaining.addAll(selected);
        Set<SelectedTag> converted = new HashSet<>();
        while (!remaining.isEmpty()) {
            SelectedTag next = null;
            for (SelectedTag candidate : remaining) {
                if (converted.containsAll(dependencies.get(candidate))) {
                    next = candidate;
                    break;
                }
            }
            if (next == null) {
                List<SelectedTag> cycle = findCycle(remaining, dependencies);
                List<String> paths = new ArrayList<>();
                for (SelectedTag tag : cycle) {
                    paths.add(tag.relativePath);
                }
                throw new IllegalArgumentException("Cyclic JSP tag dependency: " + String.join(" -> ", paths));
            }
            remaining.remove(next);
            converted.add(next);
            result.add(next);
        }
        return result;
    }

    private static List<SelectedTag> findCycle(Set<SelectedTag> remaining,
                                               Map<SelectedTag, Set<SelectedTag>> dependencies) {
        Map<SelectedTag, Integer> state = new HashMap<>();
        List<SelectedTag> stack = new ArrayList<>();
        for (SelectedTag tag : remaining) {
            List<SelectedTag> cycle = findCycle(tag, remaining, dependencies, state, stack);
            if (cycle != null) {
                return cycle;
            }
        }
        throw new IllegalStateException("Failed to locate JSP tag dependency cycle.");
    }

    private static List<SelectedTag> findCycle(SelectedTag tag, Set<SelectedTag> remaining,
                                               Map<SelectedTag, Set<SelectedTag>> dependencies,
                                               Map<SelectedTag, Integer> state, List<SelectedTag> stack) {
        Integer currentState = state.get(tag);
        if (currentState != null) {
            if (currentState == 1) {
                int start = stack.indexOf(tag);
                List<SelectedTag> cycle = new ArrayList<>(stack.subList(start, stack.size()));
                cycle.add(tag);
                return cycle;
            }
            return null;
        }
        state.put(tag, 1);
        stack.add(tag);
        for (SelectedTag dependency : dependencies.get(tag)) {
            if (!remaining.contains(dependency)) {
                continue;
            }
            List<SelectedTag> cycle = findCycle(dependency, remaining, dependencies, state, stack);
            if (cycle != null) {
                return cycle;
            }
        }
        stack.remove(stack.size() - 1);
        state.put(tag, 2);
        return null;
    }

    @SuppressWarnings("unused")
    public void replaceUsages(String jspTag, String jteTag) {
        replaceUsages(jspRoot.resolve(jspTag), jteRoot.resolve(jteTag));
    }

    public void replaceUsages(Path jspTag, Path jteTag) {
        String oldJspTagPrefix = extractTagPrefix(jspTag);
        String oldJspTagClosing = "</" + oldJspTagPrefix.substring(1) + ">";
        String newJteFile = jteRoot.relativize(jteTag).toString().replace('\\', '/');

        IoUtils.deleteFile(jspTag);

        try (Stream<Path> stream = Files.walk(jspRoot)) {
            stream.filter(Files::isRegularFile)
                    .filter(p -> !Files.isDirectory(p))
                    .filter(this::isUsageFile)
                    .forEach(jspFile -> replaceUsages(jspFile, oldJspTagPrefix, oldJspTagClosing, newJteFile));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    protected String readFile(Path jspTag) {
        return IoUtils.readFile(jspTag);
    }

    private void replaceUsages(Path jspFile, String oldJspTagPrefix, String oldJspTagClosing, String newJteFile) {
        String original = IoUtils.readFile(jspFile);
        String replaced = replaceUsages(original, oldJspTagPrefix, oldJspTagClosing, newJteFile);
        if (!replaced.equals(original)) {
            IoUtils.writeFile(jspFile, replaced);
        }
    }

    private String replaceUsages(String content, String oldJspTagPrefix, String oldJspTagClosing, String newJteFile) {
        StringBuilder jspContent = new StringBuilder(content);
        int lastIndex = 0;
        while ((lastIndex = jspContent.indexOf(oldJspTagPrefix, lastIndex)) >= 0) {
            int boundary = lastIndex + oldJspTagPrefix.length();
            if (boundary < jspContent.length()) {
                char character = jspContent.charAt(boundary);
                if (Character.isWhitespace(character) || character == '/' || character == '>') {
                    String replacement = "<" + jteTag + " jte=\"" + newJteFile + "\"";
                    jspContent.replace(lastIndex, boundary, replacement);
                    lastIndex += replacement.length();
                    continue;
                }
            }
            ++lastIndex;
        }

        lastIndex = 0;
        while ((lastIndex = jspContent.indexOf(oldJspTagClosing, lastIndex)) >= 0) {
            String replacement = "</" + jteTag + ">";
            jspContent.replace(lastIndex, lastIndex + oldJspTagClosing.length(), replacement);
            lastIndex += replacement.length();
        }
        return jspContent.toString();
    }

    private String extractTagPrefix(Path jspTag) {
        return "<" + invocationName(jspTag);
    }

    private static String invocationName(Path jspTag) {
        String fileName = jspTag.getFileName().toString();
        String tagName = fileName.substring(0, fileName.indexOf('.'));
        String namespace = jspTag.getParent().getFileName().toString();
        if ("tags".equals(namespace)) {
            namespace = "include";
        }
        return namespace + ":" + tagName;
    }

