    public String suggestJteFile(String jspFile) {
        int fileSeparatorIndex = jspFile.indexOf('.');
        if (fileSeparatorIndex == -1) {
            throw new IllegalArgumentException("JSP file without file extension " + jspFile);
        }

        StringBuilder jteFile = new StringBuilder(jspFile.substring(0, fileSeparatorIndex));
        CamelCaseConverter.convertTo(jteFile);
        jteFile.append(".jte");
        return jteFile.toString();
    }

    protected void checkDependencies(String jteCode) {
        List<String> unresolvedJspTags = findUnresolvedJspTags(jteCode);
        if (unresolvedJspTags.isEmpty()) {
            return;
        }

        Set<String> notConvertedTagsSet = getNotConvertedTagsAsSet();
        Set<String> errors = new LinkedHashSet<>();
        for (String unresolvedJspTag : unresolvedJspTags) {
            if (!notConvertedTagsSet.contains(unresolvedJspTag)) {
                errors.add("The tag " + unresolvedJspTag + "/> is used by this tag and not converted to jte yet. You should convert " + unresolvedJspTag + "/> first. If this is a tag that should be always converted by hand, implement getNotConvertedTags() and add it there.");
            }
        }
        if (!errors.isEmpty()) {
            throw new UnsupportedOperationException(String.join("\n", errors));
        }
    }

    private Set<String> getNotConvertedTagsAsSet() {
        String[] notConvertedTags = getNotConvertedTags();
        Set<String> notConvertedTagsSet = new HashSet<>();
        if (notConvertedTags != null) {
            for (String notConvertedTag : notConvertedTags) {
                notConvertedTagsSet.add("<" + notConvertedTag);
            }
        }
        return notConvertedTagsSet;
    }

    protected List<String> findUnresolvedJspTags(String jteCode) {
        List<String> result = new ArrayList<>();
        Matcher matcher = UNCONVERTED_TAG_REFERENCES.matcher(jteCode);
        while (matcher.find()) {
            result.add(matcher.group());
        }
        return result;
    }

    protected String[] getNotConvertedTags() {
        return null;
    }

    private static final class SelectedTag {
        private final String relativePath;
        private final Path source;
        private final String invocationName;
        private Path destination;

        private SelectedTag(String relativePath, Path source, String invocationName) {
            this.relativePath = relativePath;
            this.source = source;
            this.invocationName = invocationName;
        }
    }

    private static final class PlannedTagConverter implements CustomTagConverter {
        private final String jteTagPath;

        private PlannedTagConverter(String jteTagPath) {
            this.jteTagPath = jteTagPath;
        }

        @Override
        public void convert(JtpConverter converter, JtpCustomTag tag, ConverterOutput output, BodyConverter bodyConverter) throws JasperException {
            Attributes attributes = tag.getAttributes();
            String tagCall = jteTagPath.substring(0, jteTagPath.length() - 4).replace('/', '.');
            String indentation = String.valueOf(output.getIndentationChar()).repeat(output.getCurrentLineCharCount());
            output.append("@template.").append(tagCall).append("(");
            boolean first = true;
            for (int index = 0; index < attributes.getLength(); index++) {
                if (!first) {
                    output.append(",");
                }
                output.newLine(indentation);
                output.indent(1);
                output.append(attributes.getLocalName(index)).append(" = ")
                        .append(JspExpressionConverter.convertAttributeValue(attributes.getValue(index)));
                first = false;
            }
            if (tag.hasBody()) {
                if (!first) {
                    output.append(",");
                }
                output.newLine(indentation);
                output.indent(1);
                output.append("bodyContent = @`");
                bodyConverter.convert();
                output.append("`");
                first = false;
            }
            if (!first) {
                output.newLine(indentation);
            }
            output.append(")");
        }
    }
}
