    @TempDir
    Path tempDir;

    @Test
    void plansAndCommitsDependenciesInDeterministicOrder() throws IOException {
        Path jspRoot = Files.createDirectories(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        write(jspRoot.resolve("my/base.tag"), "<%@ attribute name=\"value\" type=\"java.lang.String\" %>${value}");
        write(jspRoot.resolve("my/parent.tag"), "<my:base value=\"hello\"/>");
        write(jspRoot.resolve("usage.jsp"), "<my:parent/><my:base value=\"usage\"/>");

        JspMigrationPlan plan = converter(jspRoot, jteRoot).planTags(List.of("my/parent.tag", "my/base.tag"), null);

        assertThat(plan.getConversionOrder()).containsExactly(
                jspRoot.resolve("my/base.tag").toAbsolutePath().normalize(),
                jspRoot.resolve("my/parent.tag").toAbsolutePath().normalize());
        assertThat(plan.getDeletes()).hasSize(2);
        assertThat(plan.getWrites()).containsKeys(
                jteRoot.resolve("my/base.jte").toAbsolutePath().normalize(),
                jteRoot.resolve("my/parent.jte").toAbsolutePath().normalize(),
                jspRoot.resolve("usage.jsp").toAbsolutePath().normalize());
        assertThatThrownBy(() -> plan.getDeletes().clear()).isInstanceOf(UnsupportedOperationException.class);
        assertThat(Files.exists(jteRoot)).isFalse();
        assertThat(jspRoot.resolve("my/base.tag")).exists();

        plan.commit();

        assertThat(jspRoot.resolve("my/base.tag")).doesNotExist();
        assertThat(jspRoot.resolve("my/parent.tag")).doesNotExist();
        assertThat(jteRoot.resolve("my/base.jte")).hasContent("@param String value\n${value}");
        assertThat(jteRoot.resolve("my/parent.jte")).hasContent("@template.my.base(\n    value = \"hello\"\n)");
        assertThat(jspRoot.resolve("usage.jsp")).hasContent("<my:jte jte=\"my/parent.jte\"/><my:jte jte=\"my/base.jte\" value=\"usage\"/>");
        assertThatThrownBy(plan::commit).isInstanceOf(IllegalStateException.class);
    }

    @Test
    void dependenciesInCommentsAreIgnoredButApprovedIncludesAreParsed() {
        Path jspRoot = mkdir(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        write(jspRoot.resolve("my/base.tag"), "base");
        write(jspRoot.resolve("my/parent.tag"), "<%@ include file=\"/shared.jsp.inc\" %><%-- <my:parent/> --%>");
        write(jspRoot.resolve("shared.jsp.inc"), "<my:base/>");

        JspMigrationPlan plan = converter(jspRoot, jteRoot).planTags(
                List.of("my/parent.tag", "my/base.tag"), converter -> converter.addInlinedInclude("/shared.jsp.inc"));

        assertThat(plan.getConversionOrder()).containsExactly(
                jspRoot.resolve("my/base.tag").toAbsolutePath().normalize(),
                jspRoot.resolve("my/parent.tag").toAbsolutePath().normalize());
    }

    @Test
    void reportsDeterministicClosedCycle() {
        Path jspRoot = mkdir(tempDir.resolve("jsp"));
        write(jspRoot.resolve("my/a.tag"), "<my:b/>");
        write(jspRoot.resolve("my/b.tag"), "<my:a/>");

        assertThatThrownBy(() -> converter(jspRoot, tempDir.resolve("jte"))
                .planTags(List.of("my/b.tag", "my/a.tag"), null))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessage("Cyclic JSP tag dependency: my/a.tag -> my/b.tag -> my/a.tag");
    }

    @Test
    void stalePlanListsAllChangedPathsWithoutMutating() {
        Path jspRoot = mkdir(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        Path tag = write(jspRoot.resolve("my/simple.tag"), "simple");
        Path usage = write(jspRoot.resolve("usage.jsp"), "<my:simple/>");
        JspMigrationPlan plan = converter(jspRoot, jteRoot).planTags(List.of("my/simple.tag"), null);
        Path destination = jteRoot.resolve("my/simple.jte").toAbsolutePath().normalize();

        write(tag, "changed");
        write(usage, "changed usage");
        write(destination, "occupied");

        assertThatThrownBy(plan::commit).isInstanceOfSatisfying(StaleJspMigrationPlanException.class, exception ->
                assertThat(exception.getChangedPaths()).containsExactly(
                        tag.toAbsolutePath().normalize(),
                        usage.toAbsolutePath().normalize(),
                        destination));
        assertThat(tag).hasContent("changed");
        assertThat(destination).hasContent("occupied");
    }

    @Test
    void ioFailureRestoresEarlierMutationsAndCreatedDirectories() {
        Path jspRoot = mkdir(tempDir.resolve("jsp"));
        Path jteRoot = tempDir.resolve("jte");
        write(jspRoot.resolve("my/base.tag"), "base");
        write(jspRoot.resolve("my/parent.tag"), "<my:base/>");
        JspToJteConverter converter = new TestConverter(jspRoot, jteRoot, Map.of(
                "my/base.tag", "generated/base.jte",
                "my/parent.tag", "blocked/parent.jte"));
        JspMigrationPlan plan = converter.planTags(List.of("my/base.tag", "my/parent.tag"), null);
        write(jteRoot.resolve("blocked"), "not a directory");

        assertThatThrownBy(plan::commit).isInstanceOf(IOException.class);

        assertThat(jteRoot.resolve("generated/base.jte")).doesNotExist();
        assertThat(jteRoot.resolve("generated")).doesNotExist();
        assertThat(jspRoot.resolve("my/base.tag")).hasContent("base");
        assertThat(jspRoot.resolve("my/parent.tag")).hasContent("<my:base/>");
        assertThat(jteRoot.resolve("blocked")).hasContent("not a directory");
    }

    private JspToJteConverter converter(Path jspRoot, Path jteRoot) {
        return new TestConverter(jspRoot, jteRoot, Map.of());
    }

    private static Path mkdir(Path path) {
        try {
            return Files.createDirectories(path);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static Path write(Path path, String content) {
        try {
            Files.createDirectories(path.getParent());
            return Files.writeString(path, content);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static class TestConverter extends JspToJteConverter {
        private final Path jspRoot;
        private final Map<String, String> destinations;

        private TestConverter(Path jspRoot, Path jteRoot, Map<String, String> destinations) {
            super(jspRoot, jteRoot, "my:jte");
            this.jspRoot = jspRoot;
            this.destinations = destinations;
        }

        @Override
        protected URL getResourceBase() {
            try {
                return jspRoot.toUri().toURL();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public String suggestJteFile(String jspFile) {
            return destinations.getOrDefault(jspFile, super.suggestJteFile(jspFile));
        }
    }
}
